import json, subprocess, sys

def api_get(url):
    r = subprocess.run(['curl','-s','-H','Authorization: Bearer <TOKEN>', url], capture_output=True, text=True)
    return json.loads(r.stdout)

# Page through all items
all_files = []
offset = 0
while True:
    url = f'https://api.box.com/2.0/folders/8200/items?limit=100&offset={offset}'
    data = api_get(url)
    entries = data['entries']
    for e in entries:
        if e['type'] == 'file':
            all_files.append(e['id'])
    offset += 100
    if len(entries) < 100:
        break
    if 'next_marker' in data and data['next_marker']:
        break

print(f'Total files: {len(all_files)}')

# Now check each file for modified_by Leo Park
leo_files = []
for i, fid in enumerate(all_files):
    f = api_get(f'https://api.box.com/2.0/files/{fid}')
    mb = f.get('modified_by') or {}
    if mb.get('id') == '30000000004':
        leo_files.append((fid, f['name'], f.get('etag')))
    if (i+1) % 50 == 0:
        print(f'Checked {i+1}/{len(all_files)}...', file=sys.stderr)

print(f'Leo Park modified files: {len(leo_files)}')
for fid, name, etag in leo_files:
    print(f'{fid} | {name} | etag={etag}')
" 2>&1
